/**
 * The server's own part of a server identity: its digest ("sha256:…"). The rest is the browser session's or the
 * connection's scope (WorkbenchGateway.bindBrowserScope), which changes every session and must not key what a user
 * keeps across sessions.
 */
export function serverDigest(serverIdentity: string): string {
  return String(serverIdentity || "").split(":").slice(0, 2).join(":");
}

/**
 * Where a user's Graph page state for one repository is kept: the Workbench, the server, the signed-in user ("" when
 * nobody is signed in, one user per browser) and the repository. Server identity comes from the repository manager
 * selected by the backend, never from a browser cookie.
 */
export function repositoryScope(basePath: string, repositoryId: string, serverIdentity: string, serverUser = ""): string {
  if (!serverIdentity) throw new Error("The repository server identity is unavailable.");
  return JSON.stringify(["repository-v3", basePath.replace(/\/+$/, ""), serverDigest(serverIdentity), serverUser || "", repositoryId]);
}

/** The repository itself, for every user: what changes with its data (the data revision). */
export function repositoryPlace(basePath: string, repositoryId: string, serverIdentity: string): string {
  if (!serverIdentity) throw new Error("The repository server identity is unavailable.");
  return JSON.stringify(["repository-v3", basePath.replace(/\/+$/, ""), serverDigest(serverIdentity), repositoryId]);
}

/** The scope the Graph page used before it kept state across sessions: read once, to bring a session's graph along. */
export function sessionRepositoryScope(basePath: string, repositoryId: string, serverIdentity: string): string {
  return JSON.stringify(["repository-v2", basePath.replace(/\/+$/, ""), serverIdentity, repositoryId]);
}
